:root{--color-primary:#1b8168;--color-on-primary:#fff;--color-primary-soft:#dcf5ec;--color-focus-ring:#1b8168;
--color-accent-soft:#eaf2ce;--color-accent-fg:#56701f;--color-cream:#f4f8f0;--color-stage:#edf1ea;--color-line:#e2eadf;
--color-line-strong:#cbdac7;--color-paper:#fff;--color-ink:#1e2e27;--color-ink-soft:#5c7069;--color-danger:#b23b3b;
--color-danger-soft:#f6e4e2;--font-serif:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;--font-sans:"Figtree","Segoe UI",system-ui,sans-serif}
.stage{background:var(--color-stage);padding:24px 12px;display:flex;justify-content:center;font-family:var(--font-sans);color:var(--color-ink)}
.phone{width:390px;max-width:100%;background:var(--color-cream);border-radius:36px;box-shadow:0 10px 40px rgb(0 0 0/.12);overflow:hidden;display:flex;flex-direction:column;min-height:780px}
.topbar{height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;font-weight:800;font-family:var(--font-serif);font-size:18px}
.topbar small{font-family:var(--font-sans);font-size:12px;color:var(--color-ink-soft);font-weight:700}
.content{padding:8px 16px 16px;flex:1;display:flex;flex-direction:column}
.sub{display:flex;align-items:center;gap:10px;margin-bottom:12px}
.back{width:44px;height:44px;border-radius:999px;border:1.5px solid var(--color-line);background:var(--color-paper);display:flex;align-items:center;justify-content:center;font-size:18px;cursor:pointer}
.sub h1{font-family:var(--font-serif);font-size:26px;font-weight:800;letter-spacing:-.01em;margin:0}
.frame{flex:1;border:2px dashed var(--color-line-strong);border-radius:20px;padding:12px;position:relative;background:var(--color-cream)}
.frame-tag{position:absolute;top:-10px;right:12px;background:var(--color-stage);color:var(--color-ink-soft);font-size:10px;font-weight:800;padding:1px 8px;border-radius:8px;letter-spacing:.04em}
.lead{margin:0 0 14px;font-size:15px;color:var(--color-ink-soft);line-height:1.35}
.form{display:flex;flex-direction:column;gap:14px}
.label{display:block;margin-bottom:6px;font-size:14px;font-weight:700}
.label .opt{font-weight:600;color:var(--color-ink-soft);font-size:12px;margin-left:4px}
.input{height:48px;width:100%;box-sizing:border-box;border-radius:16px;border:1.5px solid var(--color-line);background:var(--color-paper);padding:0 16px;font-size:16px;color:var(--color-ink);display:flex;align-items:center}
.input.ph{color:#9aa9a3}
.input.invalid{border-color:var(--color-danger)}
.textarea{min-height:96px;align-items:flex-start;padding-top:12px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.err{margin-top:6px;font-size:13px;font-weight:700;color:var(--color-danger)}
.hint{margin-top:6px;font-size:12px;color:var(--color-ink-soft)}
.banner-drop{height:150px;border-radius:22px;border:1.5px dashed var(--color-line-strong);background:var(--color-paper);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;color:var(--color-ink-soft);font-size:14px;cursor:pointer}
.banner-drop b{color:var(--color-primary);font-size:15px}
.banner-img{height:150px;border-radius:22px;background:linear-gradient(135deg,#6fb6b8,#a9c24f 60%,#3fb68f);position:relative;overflow:hidden}
.banner-img .acts{position:absolute;right:10px;bottom:10px;display:flex;gap:8px}
.chip{background:rgb(20 28 24/.75);color:#eaf2e9;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:800}
.loc{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:48px;border-radius:16px;border:1.5px solid var(--color-line);background:var(--color-paper);padding:8px 14px;cursor:pointer}
.loc b{display:block;font-size:15px}.loc span{font-size:12px;color:var(--color-ink-soft)}
.btn{min-height:52px;border-radius:999px;border:0;background:var(--color-primary);color:var(--color-on-primary);font-size:16px;font-weight:800;display:flex;align-items:center;justify-content:center;cursor:pointer;width:100%}
.btn.dis{opacity:.6}
.ghost{min-height:48px;border-radius:999px;border:1.5px solid var(--color-line);background:var(--color-paper);color:var(--color-ink);font-size:15px;font-weight:800;display:flex;align-items:center;justify-content:center;cursor:pointer;width:100%}
.alertbox{border-radius:18px;background:var(--color-danger-soft);color:var(--color-danger);padding:12px 14px;font-size:13px;font-weight:700}
.status{border-radius:28px;background:var(--color-primary-soft);padding:24px 18px;text-align:center;display:flex;flex-direction:column;gap:8px;align-items:center}
.status .t{font-family:var(--font-serif);font-size:22px;font-weight:800}
.status .s{font-size:14px;color:var(--color-ink-soft)}
.thumb{width:100%;height:110px;border-radius:18px;background:linear-gradient(135deg,#6fb6b8,#a9c24f 60%,#3fb68f)}
.steps{display:flex;flex-direction:column;gap:10px;background:var(--color-paper);border:1px solid var(--color-line);border-radius:22px;padding:16px}
.step{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700}
.dot{width:22px;height:22px;border-radius:999px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800}
.dot.ok{background:var(--color-primary);color:#fff}.dot.run{border:3px solid var(--color-primary-soft);border-top-color:var(--color-primary)}.dot.wait{border:1.5px solid var(--color-line-strong)}
.bar{height:8px;border-radius:999px;background:var(--color-stage);overflow:hidden}.bar i{display:block;height:100%;width:62%;background:var(--color-primary)}
.sheet-scrim{position:absolute;inset:0;background:rgb(20 28 24/.55);border-radius:20px;display:flex;align-items:flex-end}
.sheet{background:var(--color-paper);border-radius:24px 24px 0 0;width:100%;padding:16px;display:flex;flex-direction:column;gap:10px}
.sheet h2{font-family:var(--font-serif);font-size:20px;margin:0;display:flex;justify-content:space-between}
.opt-row{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:16px;border:1.5px solid var(--color-line)}
.opt-row.sel{border-color:var(--color-primary);background:var(--color-primary-soft)}
.toast{position:absolute;left:16px;right:16px;bottom:84px;background:var(--color-ink);color:#eaf2e9;border-radius:18px;padding:12px 16px;font-size:14px;font-weight:700}
.tiles{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.tile{background:var(--color-paper);border:1px solid var(--color-line);border-radius:22px;padding:16px;min-height:96px}
.tile b{display:block;font-family:var(--font-serif);font-size:17px}.tile span{font-size:12px;color:var(--color-ink-soft)}
.nav{height:64px;border-top:1px solid var(--color-line);background:var(--color-paper);display:flex;justify-content:space-around;align-items:center;font-size:11px;color:var(--color-ink-soft);font-weight:700}
.nav .plus{width:46px;height:46px;border-radius:999px;background:var(--color-primary);color:#fff;font-size:24px;display:flex;align-items:center;justify-content:center}
.empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:40px 10px;background:var(--color-paper);border:1px solid var(--color-line);border-radius:24px}
.empty .ic{width:56px;height:56px;border-radius:999px;background:var(--color-accent-soft);display:flex;align-items:center;justify-content:center;font-size:26px}

