.ghost{min-height:48px;border-radius:999px;border:1.5px solid var(--color-line);background:var(--color-paper);color:var(--color-ink);font-size:15px;font-weight:800;display:flex;align-items:center;justify-content:center;cursor:pointer;width:100%}
.alertbox{border-radius:18px;background:var(--color-danger-soft);color:var(--color-danger);padding:12px 14px;font-size:13px;font-weight:700}
.status{border-radius:28px;background:var(--color-primary-soft);padding:24px 18px;text-align:center;display:flex;flex-direction:column;gap:8px;align-items:center}
.status .t{font-family:var(--font-serif);font-size:22px;font-weight:800}
.status .s{font-size:14px;color:var(--color-ink-soft)}
.thumb{width:100%;height:110px;border-radius:18px;background:linear-gradient(135deg,#6fb6b8,#a9c24f 60%,#3fb68f)}
.steps{display:flex;flex-direction:column;gap:10px;background:var(--color-paper);border:1px solid var(--color-line);border-radius:22px;padding:16px}
.step{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700}
.dot{width:22px;height:22px;border-radius:999px;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800}
.dot.ok{background:var(--color-primary);color:#fff}.dot.run{border:3px solid var(--color-primary-soft);border-top-color:var(--color-primary)}.dot.wait{border:1.5px solid var(--color-line-strong)}
.bar{height:8px;border-radius:999px;background:var(--color-stage);overflow:hidden}.bar i{display:block;height:100%;width:62%;background:var(--color-primary)}
.sheet-scrim{position:absolute;inset:0;background:rgb(20 28 24/.55);border-radius:20px;display:flex;align-items:flex-end}
.sheet{background:var(--color-paper);border-radius:24px 24px 0 0;width:100%;padding:16px;display:flex;flex-direction:column;gap:10px}
.sheet h2{font-family:var(--font-serif);font-size:20px;margin:0;display:flex;justify-content:space-between}
.opt-row{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:16px;border:1.5px solid var(--color-line)}
.opt-row.sel{border-color:var(--color-primary);background:var(--color-primary-soft)}
.toast{position:absolute;left:16px;right:16px;bottom:84px;background:var(--color-ink);color:#eaf2e9;border-radius:18px;padding:12px 16px;font-size:14px;font-weight:700}
.tiles{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.tile{background:var(--color-paper);border:1px solid var(--color-line);border-radius:22px;padding:16px;min-height:96px}
.tile b{display:block;font-family:var(--font-serif);font-size:17px}.tile span{font-size:12px;color:var(--color-ink-soft)}
.nav{height:64px;border-top:1px solid var(--color-line);background:var(--color-paper);display:flex;justify-content:space-around;align-items:center;font-size:11px;color:var(--color-ink-soft);font-weight:700}
.nav .plus{width:46px;height:46px;border-radius:999px;background:var(--color-primary);color:#fff;font-size:24px;display:flex;align-items:center;justify-content:center}
.empty{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:40px 10px;background:var(--color-paper);border:1px solid var(--color-line);border-radius:24px}
.empty .ic{width:56px;height:56px;border-radius:999px;background:var(--color-accent-soft);display:flex;align-items:center;justify-content:center;font-size:26px}
